xib(){ jq -n --arg tag "$1" --arg path "$CDN_PATH" --argjson port "$CDN_PORT" '{tag:$tag,port:$port,listen:"127.0.0.1",protocol:"vless",settings:{clients:[],decryption:"none"},sniffing:{enabled:true,destOverride:["http","tls","quic"]},streamSettings:{network:"xhttp",security:"none",xhttpSettings:{host:"",mode:"packet-up",path:$path,xmux:{cMaxReuseTimes:"0",maxConcurrency:"16-32",hKeepAlivePeriod:0,hMaxRequestTimes:"300-600",hMaxReusableSecs:"900-1800"},seqKey:"offset",headers:{},noSSEHeader:false,xPaddingKey:"_token",noGRPCHeader:false,seqPlacement:"query",sessionIDKey:"sid",uplinkDataKey:"",xPaddingBytes:"4-10",sessionIDTable:"kdleowms............",xPaddingHeader:"X-Client-Version",xPaddingMethod:"tokenish",sessionIDLength:"16-24",uplinkChunkSize:0,uplinkHTTPMethod:"GET",xPaddingObfsMode:true,xPaddingPlacement:"query",scMaxBufferedPosts:50,scMaxEachPostBytes:"500000-1000000",sessionIDPlacement:"path",uplinkDataPlacement:"body",scMinPostsIntervalMs:"50-150",scStreamUpServerSecs:"20-80",serverMaxHeaderBytes:0}}}'; }
add_ib(){ local out c b; out=$(api GET "/api/config-profiles/$1"); c=$(printf '%s\n' "$out"|head -n1); b=$(printf '%s\n' "$out"|tail -n +2); ok "$c" || return 1; CREATED_INBOUND=$(printf '%s' "$b"|jq -r --arg t "$2" '.response.inbounds[]?|select(.tag==$t)|.uuid'|head -n1); if [[ -n "$CREATED_INBOUND" ]]; then echo "инбаунд есть $CREATED_INBOUND"; return 0; fi; local ib cfg payload; ib=$(xib "$2"); cfg=$(printf '%s' "$b"|jq --argjson ib "$ib" '.response.config.inbounds += [$ib]'); payload=$(jq -n --arg u "$1" --arg n "$(printf '%s' "$b"|jq -r '.response.name')" --argjson c "$cfg" '{uuid:$u,name:$n,config:$c}'); out=$(api PATCH /api/config-profiles "$payload"); c=$(printf '%s\n' "$out"|head -n1); b=$(printf '%s\n' "$out"|tail -n +2); ok "$c" || { echo "ошибка инбаунда $c"; return 1; }; CREATED_INBOUND=$(printf '%s' "$b"|jq -r --arg t "$2" '.response.inbounds[]?|select(.tag==$t)|.uuid'|head -n1); echo "инбаунд $CREATED_INBOUND"; }
en_node(){ local out c b; out=$(api GET "/api/nodes/$1"); c=$(printf '%s\n' "$out"|head -n1); b=$(printf '%s\n' "$out"|tail -n +2); ok "$c" || return 1; local uu payload; uu=$(printf '%s' "$b"|jq -c --arg i "$3" '[.response.configProfile.activeInbounds[].uuid]|if index($i) then . else . + [$i] end'); payload=$(jq -n --arg u "$1" --arg p "$2" --argjson a "$uu" '{uuid:$u,configProfile:{activeConfigProfileUuid:$p,activeInbounds:$a}}'); out=$(api PATCH /api/nodes "$payload"); c=$(printf '%s\n' "$out"|head -n1); ok "$c" || return 1; echo "включён на ноде"; }
add_sq(){ local out c b; out=$(api GET /api/internal-squads); c=$(printf '%s\n' "$out"|head -n1); b=$(printf '%s\n' "$out"|tail -n +2); local name uu payload; name=$(printf '%s' "$b"|jq -r --arg u "$1" '.internalSquads[]|select(.uuid==$u)|.name'); uu=$(printf '%s' "$b"|jq -c --arg u "$1" --arg i "$2" '.internalSquads[]|select(.uuid==$u)|[.inbounds[].uuid]|if index($i) then . else . + [$i] end'); payload=$(jq -n --arg u "$1" --arg n "$name" --argjson a "$uu" '{uuid:$u,name:$n,inbounds:$a}'); out=$(api PATCH /api/internal-squads "$payload"); c=$(printf '%s\n' "$out"|head -n1); ok "$c" || return 1; echo "сквад $name"; }
mk_host(){ local extra payload out c; extra=$(jq -n '{mode:"packet-up",xmux:{cMaxReuseTimes:"0",maxConcurrency:"16-32",hKeepAlivePeriod:0,hMaxRequestTimes:"300-600",hMaxReusableSecs:"900-1800"},seqKey:"offset",headers:{},noSSEHeader:false,xPaddingKey:"_token",noGRPCHeader:false,seqPlacement:"query",sessionIDKey:"sid",uplinkDataKey:"",xPaddingBytes:"4-10",sessionIDTable:"kdleowms............",xPaddingHeader:"X-Client-Version",xPaddingMethod:"tokenish",sessionIDLength:"16-24",uplinkChunkSize:0,uplinkHTTPMethod:"GET",xPaddingObfsMode:true,xPaddingPlacement:"query",scMaxBufferedPosts:50,scMaxEachPostBytes:"500000-1000000",sessionIDPlacement:"path",uplinkDataPlacement:"body",scMinPostsIntervalMs:"50-150",scStreamUpServerSecs:"20-80",serverMaxHeaderBytes:0}'); payload=$(jq -n --arg r "$1" --arg d "$2" --arg path "$CDN_PATH" --arg p "$3" --arg i "$4" --arg n "$5" --argjson e "$extra" '{remark:$r,address:$d,port:443,path:$path,sni:$d,host:$d,alpn:"h2",fingerprint:"firefox",isDisabled:false,securityLayer:"TLS",xhttpExtraParams:$e,isHidden:false,viewPosition:90,inbound:{configProfileUuid:$p,configProfileInboundUuid:$i},nodes:[$n]}'); out=$(api POST /api/hosts "$payload"); c=$(printf '%s\n' "$out"|head -n1); ok "$c" || { echo "ошибка хоста $c"; return 1; }; echo "хост создан"; }
nginx_conf(){ cat <<EOF
upstream xray_xhttp { server 127.0.0.1:${CDN_PORT}; keepalive 128; }
server {
  listen 443 ssl http2;
  server_name $1;
  ssl_certificate $2/fullchain.pem;
  ssl_certificate_key $2/privkey.pem;
  location = /health { default_type application/json; return 200 '{"status":"ok","service":"media-gateway","version":"4.2.1"}'; }
  location /static/media/live/segment0.ts/ {
    proxy_pass http://xray_xhttp; proxy_http_version 1.1; proxy_set_header Connection "";
    proxy_set_header Host \$host; proxy_buffering off; proxy_request_buffering off; proxy_read_timeout 1h; client_max_body_size 0;
    add_header Cache-Control "no-store" always; add_header CDN-Cache-Control "no-store" always;
  }
  location / { root /var/www/html; try_files \$uri \$uri/ =404; }
}
EOF
}
apply_nginx(){ command -v sshpass >/dev/null || { echo "нужен sshpass"; return 1; }; nginx_conf "$4" "$5" | sshpass -p "$3" ssh -o StrictHostKeyChecking=accept-new "$2@$1" "cat > /etc/nginx/sites-available/cdn-origin.conf && ln -sf /etc/nginx/sites-available/cdn-origin.conf /etc/nginx/sites-enabled/cdn-origin.conf && nginx -t && systemctl reload nginx"; }
yes(){ local a; read -r -p "$1 [y/N]: " a; [[ "$a" == y || "$a" == Y || "$a" == д || "$a" == Д ]]; }
on_err(){ echo "ОШИБКА: $1"; echo "1 повтор  2 пропуск  3 исправления  4 стоп"; read -r -p "> " c; case "$c" in 1) return 10;; 2) return 20;; 3) fix_menu; return 20;; *) return 30;; esac; }
wizard(){ require_panel || return; local out c b; out=$(api GET /api/nodes); c=$(printf '%s\n' "$out"|head -n1); b=$(printf '%s\n' "$out"|tail -n +2); ok "$c" || return; select_node "$b" || return; local saved domain origin ssh_host ssh_user ssh_pass cert remark; saved=$(node_get "$SELECTED_UUID"); domain=$(printf '%s' "$saved"|jq -r '.cdn_domain//empty'); origin=$(printf '%s' "$saved"|jq -r '.origin_port//443'); ssh_host=$(printf '%s' "$saved"|jq -r '.ssh_host//empty'); ssh_user=$(printf '%s' "$saved"|jq -r '.ssh_user//"root"'); ssh_pass=$(printf '%s' "$saved"|jq -r '.ssh_pass//empty'); read -r -p "Домен CDN [${domain:-}]: " di; domain="${di:-$domain}"; [[ -z "$domain" ]] && return; read -r -p "Хост [4G $SELECTED_NAME]: " remark; remark="${remark:-4G $SELECTED_NAME}"; read -r -p "Origin порт [$origin]: " oi; origin="${oi:-$origin}"; select_squad || return; read -r -p "SSH хост [${ssh_host:-$SELECTED_ADDR}]: " sh; ssh_host="${sh:-${ssh_host:-$SELECTED_ADDR}}"; read -r -p "SSH user [$ssh_user]: " su; ssh_user="${su:-$ssh_user}"; read -r -s -p "SSH пароль [${ssh_pass:+сохранён}]: " sp; echo; ssh_pass="${sp:-$ssh_pass}"; read -r -p "Сертификат [/etc/letsencrypt/live/$SELECTED_ADDR]: " cert; cert="${cert:-/etc/letsencrypt/live/$SELECTED_ADDR}"; node_save "$SELECTED_UUID" "$SELECTED_NAME" "$SELECTED_ADDR" "$ssh_host" "$ssh_user" "$ssh_pass" "$origin" "$domain"; echo "нода сохранена"; local tag; tag=$(printf '%s-CDN-XHTTP' "$SELECTED_NAME"|tr ' ' '-'|tr -cd '[:alnum:]-_'); hr; echo "нода $SELECTED_NAME | $tag | сквад $SELECTED_SQUAD_NAME | $remark -> $domain | origin $SELECTED_ADDR:$origin"; yes "Создать?" || return; while true; do add_ib "$SELECTED_PROFILE" "$tag" && break; on_err инбаунд; local rc=$?; [[ $rc -eq 30 ]] && return; [[ $rc -eq 20 ]] && break; done; while true; do en_node "$SELECTED_UUID" "$SELECTED_PROFILE" "$CREATED_INBOUND" && break; on_err нода; local rc=$?; [[ $rc -eq 30 ]] && return; [[ $rc -eq 20 ]] && break; done; while true; do add_sq "$SELECTED_SQUAD_UUID" "$CREATED_INBOUND" && break; on_err сквад; local rc=$?; [[ $rc -eq 30 ]] && return; [[ $rc -eq 20 ]] && break; done; while true; do mk_host "$remark" "$domain" "$SELECTED_PROFILE" "$CREATED_INBOUND" "$SELECTED_UUID" && break; on_err хост; local rc=$?; [[ $rc -eq 30 ]] && return; [[ $rc -eq 20 ]] && break; done; echo; nginx_conf "$SELECTED_ADDR" "$cert"; yes "Применить nginx по SSH?" && apply_nginx "$ssh_host" "$ssh_user" "$ssh_pass" "$SELECTED_ADDR" "$cert"; echo "mwscdn: SSL, origin $SELECTED_ADDR, порт $origin, HTTPS"; diagnose_one "$domain" "$SELECTED_ADDR" "$origin"; }
diagnose_one(){ hr; echo "CDN $1"; curl -sk --max-time 12 -w " %{http_code}\n" "https://$1/health" | head -c 180; echo; echo "origin $2:$3"; curl -sk --max-time 8 -w " %{http_code}\n" "https://$2:$3/health" | head -c 180; echo; }
diagnose_menu(){ require_panel || return; ensure_nodes; local uu=() nn=(); while IFS=$'\t' read -r u n; do uu+=("$u"); nn+=("$n"); done < <(jq -r 'to_entries[]|[.key,.value.name]|@tsv' "$NODES_FILE"); [[ ${#uu[@]} -eq 0 ]] && { echo "нет сохранённых нод"; return; }; select n in "${nn[@]}" Все Отмена; do [[ "$n" == Отмена || -z "$n" ]] && return; if [[ "$n" == Все ]]; then local u; for u in "${uu[@]}"; do local r; r=$(node_get "$u"); diagnose_one "$(printf '%s' "$r"|jq -r .cdn_domain)" "$(printf '%s' "$r"|jq -r .address)" "$(printf '%s' "$r"|jq -r .origin_port)"; done; break; fi; local i=$((REPLY-1)); local r; r=$(node_get "${uu[$i]}"); diagnose_one "$(printf '%s' "$r"|jq -r .cdn_domain)" "$(printf '%s' "$r"|jq -r .address)" "$(printf '%s' "$r"|jq -r .origin_port)"; break; done; }
fix_menu(){ require_panel || return; echo "1 включить инбаунд на ноде"; echo "2 добавить в сквад"; echo "3 nginx конфиг"; echo "4 применить nginx"; echo "5 проверить панель"; echo "0 назад"; read -r -p "> " c; case "$c" in 1|2|3|4) ensure_nodes; local uu=() nn=(); while IFS=$'\t' read -r u n; do uu+=("$u"); nn+=("$n"); done < <(jq -r 'to_entries[]|[.key,.value.name]|@tsv' "$NODES_FILE"); select n in "${nn[@]}" Отмена; do [[ "$n" == Отмена || -z "$n" ]] && return; local i=$((REPLY-1)); local u="${uu[$i]}" r addr; r=$(node_get "$u"); addr=$(printf '%s' "$r"|jq -r .address); local nj profile inbound; nj=$(api GET "/api/nodes/$u"|tail -n +2); profile=$(printf '%s' "$nj"|jq -r .response.configProfile.activeConfigProfileUuid); inbound=$(printf '%s' "$nj"|jq -r '.response.configProfile.activeInbounds[]?|select(.tag|test("CDN"))|.uuid'|head -n1); case "$c" in 1) en_node "$u" "$profile" "$inbound";; 2) select_squad && add_sq "$SELECTED_SQUAD_UUID" "$inbound";; 3) nginx_conf "$addr" "/etc/letsencrypt/live/$addr";; 4) apply_nginx "$(printf '%s' "$r"|jq -r .ssh_host)" "$(printf '%s' "$r"|jq -r .ssh_user)" "$(printf '%s' "$r"|jq -r .ssh_pass)" "$addr" "/etc/letsencrypt/live/$addr";; esac; break; done;; 5) api GET /api/nodes >/dev/null && echo "панель ок";; esac; }
list_nodes(){ ensure_nodes; jq -r 'to_entries[]|"  \(.value.name)  \(.value.address)  cdn=\(.value.cdn_domain//"-")  origin=\(.value.origin_port//"-")"' "$NODES_FILE"; }
del_node(){ ensure_nodes; local uu=() nn=(); while IFS=$'\t' read -r u n; do uu+=("$u"); nn+=("$n"); done < <(jq -r 'to_entries[]|[.key,.value.name]|@tsv' "$NODES_FILE"); [[ ${#uu[@]} -eq 0 ]] && return; select n in "${nn[@]}" Отмена; do [[ "$n" == Отмена || -z "$n" ]] && return; local i=$((REPLY-1)); local tmp; tmp=$(mktemp); jq --arg u "${uu[$i]}" 'del(.[$u])' "$NODES_FILE" > "$tmp" && mv "$tmp" "$NODES_FILE"; echo удалено; break; done; }
while true; do
  load_panel
  hr; echo "Remnawave CDN"; echo "Панель: ${PANEL_URL:-не задана}"; hr
  echo "1 Создать CDN"; echo "2 Диагностика"; echo "3 Исправления"; echo "4 Сохранённые ноды"
  echo "5 Панель сохранить/изменить"; echo "6 Удалить данные панели"; echo "7 Удалить ноду"; echo "0 Выход"
  read -r -p "> " c
  case "$c" in
    1) wizard; pause;;
    2) diagnose_menu; pause;;
    3) fix_menu; pause;;
    4) list_nodes; pause;;
    5) setup_panel; pause;;
    6) rm -f "$CONFIG_FILE"; PANEL_URL=""; TOKEN=""; echo удалено; pause;;
    7) del_node; pause;;
    0) exit 0;;
  esac
done
